// TypeScript Version: 4.1

/* eslint-disable max-lines */

/**
* Extracted block line object.
*/
interface BlockLine {
	/**
	* Line text.
	*/
	text: string;

	/**
	* Line number.
	*/
	line: number;
}

/**
* Extracted block object.
*/
interface Block {
	/**
	* File path.
	*/
	file: string;

	/**
	* Block index.
	*/
	blockIndex: number;

	/**
	* Include statements.
	*/
	includes: Array<BlockLine>;

	/**
	* Static helper functions.
	*/
	staticHelpers: Array<BlockLine>;

	/**
	* File-scope code lines.
	*/
	fileScope: Array<BlockLine>;

	/**
	* Block body code lines.
	*/
	body: Array<BlockLine>;

	/**
	* Annotations (i.e., `// returns` comments).
	*/
	annotations: Array<BlockLine>;
}

/**
* Extracts example blocks from a file.
*
* @param file - file path
* @param mode - extraction mode (e.g., `"src"` or `"markdown"`) (default: "src")
* @returns extracted blocks
*
* @example
* var join = require( 'path' ).join;
*
* var fpath = join( __dirname, '..', '..', 'test', 'fixtures', 'src', 'test_edge_cases.c' );
* var blocks = extract( fpath, 'src' );
*/
declare function extract( file: string, mode?: 'src' | 'markdown' ): Array<Block>;

// EXPORTS //

export = extract;
